const fruits = ["Apple", "Banana", "Mango"];

const [first, second, third] = fruits;

console.log(first);  // Apple
console.log(second); // Banana
console.log(third);  // Mango

// Skip an element
const [a, , c] = fruits;
console.log(a); // Apple
console.log(c); // Mango

// Rest element
const [head, ...rest] = fruits;
console.log(head); // Apple
